mapper.select:
SELECT a.QUESTION_ID_1, a.QUESTION_DSCR_1 FROM inspection.`inspection_question_ledger` a WHERE
a.`QUESTION_DSCR` <> '其他关注事项'
a.`QUESTION_DSCR` = '其他关注事项'
AND a.`TASK_ID` = #{params.TASK_ID}
AND a.ADD_USERID = #{params.ADD_USERID}
AND a.IS_REPORT = #{params.IS_REPORT}
AND a.IS_LIST = #{params.IS_LIST}
GROUP BY a.QUESTION_ID_1 ORDER BY a.ADD_DATE

SELECT a.QUESTION_ID_2, a.QUESTION_DSCR_2 FROM inspection.`inspection_question_ledger` a WHERE
a.`QUESTION_DSCR` <> '其他关注事项'
a.`QUESTION_DSCR` = '其他关注事项'
AND a.`TASK_ID` = #{params.TASK_ID}
AND a.ADD_USERID = #{params.ADD_USERID}
AND a.IS_REPORT = #{params.IS_REPORT}
AND a.IS_LIST = #{params.IS_LIST}
AND a.QUESTION_ID_1 = #{params.QUESTION_ID_1} GROUP BY a.QUESTION_ID_2 ORDER BY a.ADD_DATE

SELECT a.LEDGER_ID, a.QUESTION_ID, a.QUESTION_CONTENT, a.QUESTION_OPINIONS FROM inspection.`inspection_question_ledger` a WHERE
a.`QUESTION_DSCR` <> '其他关注事项'
a.`QUESTION_DSCR` = '其他关注事项'
AND a.`TASK_ID` = #{params.TASK_ID}
AND a.ADD_USERID = #{params.ADD_USERID}
AND a.IS_REPORT = #{params.IS_REPORT}
AND a.IS_LIST = #{params.IS_LIST}
AND TRIM(a.QUESTION_CONTENT) = TRIM(#{params.QUESTION_CONTENT})
AND a.QUESTION_ID_2 = #{params.QUESTION_ID_2} GROUP BY a.LEDGER_ID, a.QUESTION_CONTENT ORDER BY a.ADD_DATE

SELECT a.QUESTION_ID AS id, a.QUESTION_DSCR AS name, IFNULL(a.QUESTION_PID,'') AS pid, GROUP_CONCAT(d.RULE_DSCR SEPARATOR '\n') AS concent, a.isleaf, a.PATH AS path, b.TYPE, a.SORT FROM inspection.inspection_question_bank a LEFT JOIN inspection.`inspection_question_bank_type` b ON a.QUESTION_ID = b.QUESTION_ID LEFT JOIN inspection.`inspection_question_rule_relation` c ON a.`QUESTION_ID` = c.`QUESTION_ID` LEFT JOIN ( SELECT r.`RULE_ID`, CONCAT('《',r.`RULE_FILE_NAME`,'》（',r.`RULE_FILE_NO`, '）',r.`RULE_FILE_CONTENT`) AS RULE_DSCR FROM inspection.`inspection_question_rule` r ) d ON c.`RULE_ID`= d.`RULE_ID` WHERE 1=1 AND a.PATH IS NOT NULL AND a.PATH <>''
AND a.QUESTION_ID = #{params.QUESTION_ID}
AND a.QUESTION_DSCR = #{params.QUESTION_DSCR}
AND a.QUESTION_PID = #{params.QUESTION_PID}
AND (CASE WHEN a.`isleaf` = 0 THEN b.TYPE = #{params.QUESTION_TYPE} ELSE TRUE END)
GROUP BY a.QUESTION_ID ORDER BY a.SORT
